"""KTM wiring, read by eye from KTM's own wiring diagram sheets (owner-supplied 2026-11-26). First file: the
450 SX-F / XC-F sheets Y03600-01 to Y03602-01, whose title block reads 2024-2025. Component names and the colour
key come from the sheets' printed legends. Medium confidence until a second read; the sheets are not stored.
usage: python3 scripts/knowledge/wiring5.py"""
import sys,os
sys.path.insert(0,os.path.join(os.path.dirname(os.path.abspath(__file__)),'pre2020'))
from _lib import File
F=File('wiring5_ktm450_2025','w-k1','KTM 450 SX-F and 450 XC-F 2024-2025 wiring (wiring pass 2026-11)','KTM',['450 SX-F','450 XC-F'],[2024,2025])
M=['450 SX-F','450 XC-F'];Y=[2024,2025];D='ecu_electronics'
s=F.src('manufacturer','KTM wiring diagram 450 SX-F / XC-F 2024-2025, sheets Y03600-01, Y03601-01, Y03602-01','https://www.ktmshop.se/','2024')
N='Read from the wiring diagram by eye; check the diagram on the bike before cutting, splicing or back-probing.'
def R(t,st,v,c='medium'): F.R(D,t,M,Y,st,v,'OEM',s,c,N if c=='medium' else '')
R('Wire colour code and components',"KTM's wire colour letters on the 2024-2025 450 SX-F and 450 XC-F: bl black, br brown, bu blue, gn green, gr gray, lbu light blue, or orange, pk pink, pu violet, rd red, wh white, ye yellow; two colours joined by a dash are base and stripe. Parts on the diagram: engine control unit, capacitor, 12 V battery, alternator, voltage regulator, starter relay with the main fuse, power relay, starter motor, right combination switch, a separate fuse, fuel pump, injection valve, ignition coil, service hour counter, diagnostics connector, and the sensors for intake air temperature, coolant temperature, tilt, gear position, crankshaft speed, intake manifold pressure and throttle position. A connectivity unit, fuel level sensor and left combination switch are shown as fitted only on some bikes.",{'bl':'black','br':'brown','bu':'blue','gn':'green','gr':'gray','lbu':'light blue','or':'orange','pk':'pink','pu':'violet','rd':'red','wh':'white','ye':'yellow'},'high')
R('Engine control unit connector pinout',"Engine control unit pinout on the 2024-2025 450 SX-F and 450 XC-F (one 33-pin connector; pin, job, wire colour): 1 switched power in, orange; 2 power relay control, white/black; 4 injection valve, black/gray; 5 and 22 ground, brown; 7 service hour counter, white; 10 fuel pump, blue/gray; 11 ignition coil, white/violet; 12 sensor supply, blue; 13 and 14 data lines to the diagnostics connector and connectivity unit, black/blue and white/blue; 15 throttle position signal, yellow/orange; 16 tilt sensor signal, yellow/green; 17 sensor ground, black; 18 gear position signal, brown/green; 19 intake air temperature signal, red; 21 coolant temperature signal, black/yellow; 23 and 24 crankshaft speed sensor (24 is white/yellow); 26 diagnostics line, light blue; 27 intake manifold pressure signal, violet; 30 right combination switch, white/gray; 33 left combination switch, brown/violet.",
 {'1':'or','2':'wh-bl','4':'bl-gr','5':'br','22':'br','7':'wh','10':'bu-gr','11':'wh-pu','12':'bu','13':'bl-bu','14':'wh-bu','15':'ye-or','16':'ye-gn','17':'bl','18':'br-gn','19':'rd','21':'bl-ye','24':'wh-ye','26':'lbu','27':'pu','30':'wh-gr','33':'br-pu'})
R('Sensor wiring',"Sensor wiring on the 2024-2025 450 SX-F and 450 XC-F. The three-wire sensors share a blue supply wire and a black ground wire. Throttle position sensor: blue, black and a yellow/orange signal. Intake manifold pressure sensor: blue, black and a violet signal. Tilt sensor: blue, black and a yellow/green signal. Gear position sensor: blue, black and a brown/green signal. Coolant temperature sensor: black/yellow signal and black ground. Intake air temperature sensor: red signal and black ground. Crankshaft speed sensor: two wires to the control unit, one of them white/yellow. Ignition coil: white/violet from the control unit.",
 {'tps':'bu, bl, ye-or','map':'bu, bl, pu','tilt':'bu, bl, ye-gn','gear':'bu, bl, br-gn','coolant':'bl-ye, bl','iat':'rd, bl','crank':'wh-ye + one more','coil':'wh-pu'})
R('Power, charging, starting and fuel circuit',"Power circuit on the 2024-2025 450 SX-F and 450 XC-F. The alternator feeds the voltage regulator, whose output is white/red and whose ground is brown. White/red is the unswitched battery feed: it runs to the capacitor, the starter relay with its 10 A main fuse, and the power relay. The power relay is switched by the control unit on white/black and sends switched power out on orange to the control unit, the injection valve, the hour counter and a second fuse marked 5 A. From that fuse a blue/orange wire feeds the fuel pump, which the control unit switches on blue/gray. The injection valve gets orange power and is switched on black/gray. The starter button on the right combination switch sends red/blue to the starter relay; the switch's other wire to the control unit is white/gray. Heavy black cables join battery, starter relay and starter motor. Brown is ground throughout.",
 {'battery_feed':'wh-rd','switched_power':'or','ground':'br','main_fuse_a':10,'second_fuse_a':5,'fuel_pump':'bu-or feed, bu-gr control','injector':'or feed, bl-gr control','start_button':'rd-bu','power_relay_control':'wh-bl'})
R('Diagnostics connector and hour counter',"The 6-pin diagnostics connector on the 2024-2025 450 SX-F and 450 XC-F carries light blue (diagnostics line), black/blue and white/blue (data lines), brown (ground), orange (switched power) and white/black. The service hour counter connects on orange (power), white (to the control unit), brown/red and brown (ground); brown/red also runs to the fuel level sensor on bikes that have one.",{'diagnostics':'lbu, bl-bu, wh-bu, br, or, wh-bl','hour_counter':'or, wh, br-rd, br'})
F.write()
